/** Exposes the primitive-composition pipeline without disclosing renderer implementation. */
import { NextRequest, NextResponse } from "next/server";
import { compileToolCalls, composeGameFromPrompt, ComposerToolCall } from "@/agent-harness/game-composer";
import { startGameCompositionTrace } from "@/agent-harness/observability";

export const runtime = "nodejs";

/**
 * What it does: Compiles explicit tool calls or asks the composition agent to create them from a prompt.
 * Can be generated by AI?: No.
 */
export async function POST(request: NextRequest) {
  try {
    const body = await request.json() as { prompt?: unknown; toolCalls?: unknown };
    if (typeof body.prompt === "string" && body.prompt.trim()) {
      const trace = startGameCompositionTrace({ prompt: body.prompt.trim().slice(0, 1000) });
      try {
        const result = await composeGameFromPrompt(body.prompt.trim().slice(0, 1000), trace);
        trace.recordValidation({ valid: result.valid, errors: result.valid ? [] : result.errors, ...(result.valid ? { templateId: result.recipe.templateId } : {}) });
        trace.finish({ accepted: result.valid, ...(result.valid ? { templateId: result.recipe.templateId } : { validationErrors: result.errors }) });
        return NextResponse.json(result, { status: result.valid ? 200 : 422 });
      } catch (error) {
        trace.fail(error);
        throw error;
      }
    }
    if (Array.isArray(body.toolCalls)) {
      const result = compileToolCalls(body.toolCalls as ComposerToolCall[]);
      return NextResponse.json(result, { status: result.valid ? 200 : 422 });
    }
    return NextResponse.json({ error: "Provide a game prompt or a toolCalls array." }, { status: 400 });
  } catch (error) {
    return NextResponse.json({ error: error instanceof Error ? error.message : "Game composition failed." }, { status: 502 });
  }
}
